        maxQ.pollLast();
      maxQ.offerLast(nums[i]);
      if (i >= k && nums[i - k] == maxQ.peekFirst()) // out-of-bounds
        maxQ.pollFirst();
      if (i >= k - 1)
        ans[i - k + 1] = maxQ.peekFirst();
    }

