    final int leftStep = k - rightStep;
    if (leftStep < 0)
      return 0;
    return nCk(leftStep + rightStep, Math.min(leftStep, rightStep));
  }

  // C(n, k) = C(n - 1, k) + C(n - 1, k - 1)
  private int nCk(int n, int k) {
    final int MOD = 1_000_000_007;
